import React, { useState } from 'react';
import { IntlProvider } from 'react-intl';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import ColourSwatches from './index';
import type { ColourVariant } from './index';

// The icons barrel (overrides/app/components/icons/index.tsx) re-exports the SFCC icons barrel,
// which has a top-level side effect that fails under Vitest (SVG imports resolve to path strings,
// not components). Mock it at the barrel level per testing.md > "Known gap: ZimmIcon throws under Vitest".
vi.mock('../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
}));

/*
 * Deliberately NOT a re-test of what the Storybook `play` functions already cover (click moves
 * selection, label follows). Per .claude/rules/testing.md, coverage is not duplicated across
 * layers — this file targets the logic edges a story cannot cheaply enumerate:
 *
 *   - the `currentIndex === -1` backward case, where plain modulo silently lands on the
 *     second-to-last swatch instead of the last (the component carries a comment warning
 *     about exactly this — it is the kind of bug that survives a refactor invisibly)
 *   - wrap boundaries in both directions
 *   - the DIS query-string separator, which must be `&` when the resolved link already has `?`
 *   - the roving-tabIndex invariant: exactly one tab stop, always
 *
 * It is also the only layer that runs locally: `test-storybook` currently fails on every story
 * in the repo (pre-existing `StorybookTestRunnerError` env fault), so the `play` functions are
 * unverified until CI. These tests are not blocked on that.
 */

const IMG = 'https://example.test/swatch.jpg';

const variant = (value: string, name: string, over: Partial<ColourVariant> = {}): ColourVariant => ({
  value,
  name,
  imageUrl: IMG,
  orderable: true,
  ...over,
});

/** The component is controlled, so keyboard/click flows need state to move against. */
const Harness = ({ variants, initial }: { variants: readonly ColourVariant[]; initial?: string }) => {
  const [selected, setSelected] = useState<string | undefined>(initial);
  return (
    <IntlProvider locale="en" defaultLocale="en">
      <ColourSwatches variants={variants} selectedValue={selected} onSelect={setSelected} />
    </IntlProvider>
  );
};

const THREE = [variant('a', 'Alpha'), variant('b', 'Bravo'), variant('c', 'Charlie')];

const radios = () => screen.getAllByRole('radio');
const group = () => screen.getByRole('radiogroup', { name: 'Colour' });

describe('ColourSwatches — AC5 filter', () => {
  test('withholds a colour with no swatch image', () => {
    render(<Harness variants={[...THREE, variant('d', 'Delta', { imageUrl: undefined })]} initial="a" />);

    expect(radios()).toHaveLength(3);
    expect(screen.queryByRole('radio', { name: 'Delta' })).not.toBeInTheDocument();
  });

  test('withholds a colour that is not orderable even when it has a good image', () => {
    // The load-bearing half: an unorderable colour with a perfectly valid image must still
    // be absent. A filter on imageUrl alone would let this one through.
    render(<Harness variants={[...THREE, variant('d', 'Delta', { orderable: false })]} initial="a" />);

    expect(radios()).toHaveLength(3);
    expect(screen.queryByRole('radio', { name: 'Delta' })).not.toBeInTheDocument();
  });

  test('renders nothing selectable when every colour is withheld', () => {
    render(
      <Harness
        variants={[variant('a', 'Alpha', { orderable: false }), variant('b', 'Bravo', { imageUrl: undefined })]}
      />,
    );

    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
  });
});

describe('ColourSwatches — AC1 single offered colour', () => {
  test('shows the label and colour name but no swatch row', () => {
    render(<Harness variants={[variant('a', 'Alpha')]} />);

    expect(screen.getByText('Colour:')).toBeInTheDocument();
    expect(screen.getByTestId('pdp-colour-selected-name')).toHaveTextContent('Alpha');
    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
  });

  test('names the sole *offered* colour, not the sole recorded one', () => {
    // Two colours recorded, one withheld — from the shopper's side this is a single-colour
    // product, so the label must still name the surviving colour with nothing selected.
    render(<Harness variants={[variant('a', 'Alpha'), variant('b', 'Bravo', { orderable: false })]} />);

    expect(screen.getByTestId('pdp-colour-selected-name')).toHaveTextContent('Alpha');
    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
  });
});

describe('ColourSwatches — keyboard navigation', () => {
  test('ArrowLeft with nothing selected lands on the LAST swatch, not the second-to-last', async () => {
    // Regression guard for the documented modulo trap: with currentIndex === -1,
    // (-1 - 1 + 3) % 3 === 1 ('Bravo'), which is wrong. Expected is 'Charlie'.
    const user = userEvent.setup();
    render(<Harness variants={THREE} />);

    await user.keyboard('{Tab}');
    await user.keyboard('{ArrowLeft}');

    expect(screen.getByRole('radio', { name: 'Charlie' })).toHaveAttribute('aria-checked', 'true');
  });

  test('ArrowRight with nothing selected lands on the first swatch', async () => {
    const user = userEvent.setup();
    render(<Harness variants={THREE} />);

    await user.keyboard('{Tab}');
    await user.keyboard('{ArrowRight}');

    expect(screen.getByRole('radio', { name: 'Alpha' })).toHaveAttribute('aria-checked', 'true');
  });

  test('wraps forward from the last swatch to the first', async () => {
    const user = userEvent.setup();
    render(<Harness variants={THREE} initial="c" />);

    await user.keyboard('{Tab}');
    await user.keyboard('{ArrowRight}');

    expect(screen.getByRole('radio', { name: 'Alpha' })).toHaveAttribute('aria-checked', 'true');
  });

  test('wraps backward from the first swatch to the last', async () => {
    const user = userEvent.setup();
    render(<Harness variants={THREE} initial="a" />);

    await user.keyboard('{Tab}');
    await user.keyboard('{ArrowLeft}');

    expect(screen.getByRole('radio', { name: 'Charlie' })).toHaveAttribute('aria-checked', 'true');
  });

  test('ArrowDown and ArrowUp mirror ArrowRight and ArrowLeft', async () => {
    const user = userEvent.setup();
    render(<Harness variants={THREE} initial="a" />);

    await user.keyboard('{Tab}');
    await user.keyboard('{ArrowDown}');
    expect(screen.getByRole('radio', { name: 'Bravo' })).toHaveAttribute('aria-checked', 'true');

    await user.keyboard('{ArrowUp}');
    expect(screen.getByRole('radio', { name: 'Alpha' })).toHaveAttribute('aria-checked', 'true');
  });

  test('navigation skips over withheld colours because they never render', async () => {
    // 'Bravo' is unorderable, so ArrowRight from 'Alpha' must reach 'Charlie' directly.
    const user = userEvent.setup();
    render(
      <Harness
        variants={[variant('a', 'Alpha'), variant('b', 'Bravo', { orderable: false }), variant('c', 'Charlie')]}
        initial="a"
      />,
    );

    await user.keyboard('{Tab}');
    await user.keyboard('{ArrowRight}');

    expect(screen.getByRole('radio', { name: 'Charlie' })).toHaveAttribute('aria-checked', 'true');
  });

  test('does not move the selection on keys that are neither arrows nor activation', async () => {
    const onSelect = vi.fn();
    const user = userEvent.setup();
    render(
      <IntlProvider locale="en" defaultLocale="en">
        <ColourSwatches variants={THREE} selectedValue="a" onSelect={onSelect} />
      </IntlProvider>,
    );

    await user.keyboard('{Tab}');
    await user.keyboard('x');
    await user.keyboard('{Escape}');
    await user.keyboard('{Home}');

    expect(onSelect).not.toHaveBeenCalled();
  });

  test('Enter and Space activate the focused swatch', async () => {
    // Native <button> semantics, deliberately not intercepted: WAI-ARIA expects Space to
    // select a focused radio, and Enter is the conventional button activation. Both reach
    // onClick rather than the keydown handler, so they select *in place* rather than moving.
    const onSelect = vi.fn();
    const user = userEvent.setup();
    render(
      <IntlProvider locale="en" defaultLocale="en">
        <ColourSwatches variants={THREE} selectedValue="b" onSelect={onSelect} />
      </IntlProvider>,
    );

    await user.keyboard('{Tab}'); // tab stop is the selected swatch, 'Bravo'
    await user.keyboard('{Enter}');
    expect(onSelect).toHaveBeenCalledWith('b');

    onSelect.mockClear();
    await user.keyboard(' ');
    expect(onSelect).toHaveBeenCalledWith('b');
  });

  test('moves focus with the selection so arrows stay usable without re-tabbing', async () => {
    const user = userEvent.setup();
    render(<Harness variants={THREE} initial="a" />);

    await user.keyboard('{Tab}');
    await user.keyboard('{ArrowRight}');
    expect(screen.getByRole('radio', { name: 'Bravo' })).toHaveFocus();

    await user.keyboard('{ArrowRight}');
    expect(screen.getByRole('radio', { name: 'Charlie' })).toHaveFocus();
  });
});

describe('ColourSwatches — roving tabIndex', () => {
  test('exposes exactly one tab stop when a colour is selected', () => {
    render(<Harness variants={THREE} initial="b" />);

    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveAttribute('aria-label', 'Bravo');
  });

  test('falls back to the first swatch as the tab stop when nothing is selected', () => {
    render(<Harness variants={THREE} />);

    const stops = within(group())
      .getAllByRole('radio')
      .filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveAttribute('aria-label', 'Alpha');
  });
});

describe('ColourSwatches — DIS image sizing', () => {
  test('requests a scaled image rather than the full-resolution original', () => {
    render(<Harness variants={THREE} initial="a" />);

    const img = screen.getByRole('radio', { name: 'Alpha' }).querySelector('img');
    expect(img).toHaveAttribute('src', `${IMG}?sw=96&q=60`);
    // AGENTS.md > Performance requires lazy loading on images.
    expect(img).toHaveAttribute('loading', 'lazy');
  });

  test('uses & as the separator when the resolved link already carries a query string', () => {
    // `link` (the fallback when disBaseLink is absent) can arrive with params already on it.
    // A naive `?` append would produce a second `?` and break the URL.
    const withQuery = 'https://example.test/swatch.jpg?cache=1';
    render(<Harness variants={[variant('a', 'Alpha', { imageUrl: withQuery }), variant('b', 'Bravo')]} initial="a" />);

    const img = screen.getByRole('radio', { name: 'Alpha' }).querySelector('img');
    expect(img).toHaveAttribute('src', `${withQuery}&sw=96&q=60`);
  });

  test('swatch images are decorative — empty alt, name carried by the button', () => {
    render(<Harness variants={THREE} initial="a" />);

    const swatch = screen.getByRole('radio', { name: 'Alpha' });
    expect(swatch.querySelector('img')).toHaveAttribute('alt', '');
  });
});

