import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { StaticProductHeader } from './staticProductHeader';

// Chakra/SFCC primitives — mocked so Vitest doesn't need to resolve their asset/SVG imports.
vi.mock('@salesforce/retail-react-app/app/components/shared/ui', () => ({
  Skeleton: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
  VStack: ({ children }: { children?: React.ReactNode }) => <div>{children}</div>,
}));

vi.mock('@salesforce/retail-react-app/app/components/breadcrumb', () => ({
  default: () => <nav data-testid="breadcrumb" />,
}));

vi.mock('@salesforce/retail-react-app/app/components/product-tile/promo-callout', () => ({
  default: () => <div data-testid="promo-callout" />,
}));

// Forward name and price so tests can assert on which render branch executed.
vi.mock('app/components/ui-kits/molecules/zimmProductContent', () => ({
  ZimmProductContent: ({ name, price }: { name?: string; price?: React.ReactNode }) => (
    <div data-testid="product-content" data-has-price={String(price !== undefined)}>
      {name}
    </div>
  ),
}));

// Returns a controlled info object — selectPdpProductInfo's own logic is not under test here.
vi.mock('../productInfo', () => ({
  selectPdpProductInfo: vi.fn(() => ({
    name: 'Test Product',
    price: <span>$100.00</span>,
    description: undefined,
  })),
}));

// Minimal product shapes. Cast to `any` — the mocked selectPdpProductInfo ignores the actual
// shape, so using the full SFCC type here would only add noise without proving anything.
const PRODUCT = { id: 'p1', name: 'Test Product' } as any;
const PRODUCT_WITH_PROMO = { ...PRODUCT, productPromotions: [{ promotionId: 'promo1' }] } as any;
const CATEGORY = [{ id: 'c1', name: 'Dresses', parentCategoryId: 'root' }] as any;

const wrap = (ui: React.ReactElement) => render(<IntlProvider locale="en">{ui}</IntlProvider>);

describe('StaticProductHeader — headerCategory branch', () => {
  test('renders breadcrumb when headerCategory is provided', () => {
    wrap(<StaticProductHeader name="Test" product={PRODUCT} category={CATEGORY} />);
    expect(screen.getByTestId('breadcrumb')).toBeInTheDocument();
  });

  test('does not render breadcrumb when headerCategory is absent', () => {
    wrap(<StaticProductHeader name="Test" product={PRODUCT} />);
    expect(screen.queryByTestId('breadcrumb')).not.toBeInTheDocument();
  });
});

describe('StaticProductHeader — isProductPartOfBundle branch', () => {
  test('hides price on ZimmProductContent when product is part of a bundle', () => {
    wrap(<StaticProductHeader name="Test" product={PRODUCT_WITH_PROMO} isProductPartOfBundle />);
    expect(screen.getByTestId('product-content')).toHaveAttribute('data-has-price', 'false');
  });

  test('hides promo callout when product is part of a bundle', () => {
    wrap(<StaticProductHeader name="Test" product={PRODUCT_WITH_PROMO} isProductPartOfBundle />);
    expect(screen.queryByTestId('promo-callout')).not.toBeInTheDocument();
  });

  test('shows price on ZimmProductContent when product is not part of a bundle', () => {
    wrap(<StaticProductHeader name="Test" product={PRODUCT_WITH_PROMO} isProductPartOfBundle={false} />);
    expect(screen.getByTestId('product-content')).toHaveAttribute('data-has-price', 'true');
  });

  test('shows promo callout when product is not part of a bundle and has promotions', () => {
    wrap(<StaticProductHeader name="Test" product={PRODUCT_WITH_PROMO} isProductPartOfBundle={false} />);
    expect(screen.getByTestId('promo-callout')).toBeInTheDocument();
  });
});

describe('StaticProductHeader — afterContent branch (SFCC-91)', () => {
  test('renders afterContent below the product content block when provided', () => {
    wrap(
      <StaticProductHeader
        name="Test"
        product={PRODUCT}
        afterContent={<div data-testid="colour-swatches">swatches</div>}
      />,
    );
    const content = screen.getByTestId('product-content');
    const swatches = screen.getByTestId('colour-swatches');
    expect(swatches).toBeInTheDocument();
    // Bit 4 (DOCUMENT_POSITION_FOLLOWING): swatches must follow product-content in document order.
    expect(content.compareDocumentPosition(swatches) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  });

  test('renders nothing for afterContent when the prop is omitted', () => {
    wrap(<StaticProductHeader name="Test" product={PRODUCT} />);
    expect(screen.queryByTestId('colour-swatches')).not.toBeInTheDocument();
  });
});

