/*
 * SFCC-91 — PDP Colour Swatches & Variation Selection
 * Generated from e2e/features/pdp/SFCC-91_pdp-colour-swatches.feature (signed off 2026-08-20;
 * the non-orderable scenario was revised 2026-08-21 after the BA's AC5 clarification and
 * re-signed-off the same day).
 *
 * Every test skips until its fixture SKU is provisioned — see e2e/fixtures/products.js.
 * File extension is .js, not .ts: playwright.config.js pins `testMatch: '**\/*.spec.js'`,
 * so a .spec.ts here would be silently never discovered. See the spec doc for the open
 * Tier 1 question about widening discovery.
 */

const { test, expect } = require('@playwright/test');
const { ProductPage } = require('../../../support/pages/ProductPage');
const {
  pdpProductWithMultipleColours,
  pdpProductWithUnpopulatedColour,
  pdpProductWithNonOrderableColour,
  pdpProductWithSingleColour,
  pdpProductWithAllColoursWithheld,
  standardProduct,
} = require('../../../fixtures/products');

const TAGS = { tag: ['@pdp', '@SFCC-91'] };

test.describe('PDP UI — Colour Swatches & Variation Selection', () => {
  test('A product with only one colour shows the colour name without swatches', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithSingleColour();
    test.skip(!sku, 'No single-colour product SKU provisioned — set E2E_SINGLE_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    await expect(pdp.colourLabel).toBeVisible();
    await expect(pdp.colourSelectedName).not.toBeEmpty();
    // AC1 — the label names the colour, but there is nothing to choose between.
    await expect(pdp.colourSwatchGroup).toHaveCount(0);
  });

  test('A product with multiple colours shows one swatch per colour', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithMultipleColours();
    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    const colours = await pdp.offeredColourNames();
    expect(colours.length).toBeGreaterThanOrEqual(3);
    // Every swatch carries its own image — no empty placeholder boxes.
    for (const name of colours) {
      await expect(pdp.colourSwatch(name).locator('img')).toHaveAttribute('src', /.+/);
    }
  });

  test('The colour currently being viewed is indicated as selected', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithMultipleColours();
    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    // AC3 — exactly one swatch is selected on load, and the label agrees with it.
    await expect(pdp.selectedColourSwatch).toHaveCount(1);
    const selectedName = await pdp.selectedColourSwatch.getAttribute('aria-label');
    await expect(pdp.colourSelectedName).toHaveText(selectedName);
  });

  test('Choosing a different colour updates the address bar without reloading the page', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithMultipleColours();
    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    // Tag this document instance. A full reload would discard it — that is the assertion.
    await page.evaluate(() => {
      window.__sfcc91NoReload = true;
    });

    const colours = await pdp.offeredColourNames();
    const selectedName = await pdp.selectedColourSwatch.getAttribute('aria-label');
    const target = colours.find((name) => name !== selectedName);

    const targetValue = await pdp.colourValueFor(target);
    await pdp.selectColour(target);

    // AC4 — the ?color= param carries the chosen colour's value, not merely *a* colour.
    // searchParams decodes for us, so this compares the real value even when encoded.
    await expect.poll(() => new URL(page.url()).searchParams.get('color')).toBe(targetValue);
    await expect(pdp.colourSwatch(target)).toHaveAttribute('aria-checked', 'true');
    // No full reload, and the product content never went away.
    expect(await page.evaluate(() => window.__sfcc91NoReload)).toBe(true);
    await expect(pdp.productName).toBeVisible();
  });

  test('Choosing a different colour updates the colour label and the selected swatch', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithMultipleColours();
    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    const colours = await pdp.offeredColourNames();
    const previousName = await pdp.selectedColourSwatch.getAttribute('aria-label');
    const target = colours.find((name) => name !== previousName);

    await pdp.selectColour(target);

    await expect(pdp.colourSelectedName).toHaveText(target);
    await expect(pdp.colourSwatch(target)).toHaveAttribute('aria-checked', 'true');
    await expect(pdp.colourSwatch(previousName)).toHaveAttribute('aria-checked', 'false');
    // Selection is single-valued throughout.
    await expect(pdp.selectedColourSwatch).toHaveCount(1);
  });

  test('A colour variation with no image is not offered to the shopper', TAGS, async ({ page }) => {
    const { sku, withheldColourName } = pdpProductWithUnpopulatedColour();
    test.skip(!sku, 'No unpopulated-colour product SKU provisioned — set E2E_UNPOPULATED_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    // AC5 — the colour is absent from the group entirely, not rendered disabled.
    const colours = await pdp.offeredColourNames();
    expect(colours.length).toBeGreaterThan(1);
    if (withheldColourName) {
      // The load-bearing assertion: that specific colour is nowhere in the group.
      expect(colours).not.toContain(withheldColourName);
      await expect(pdp.colourSwatch(withheldColourName)).toHaveCount(0);
    }
    // Every swatch that IS offered has a real image behind it.
    for (const name of colours) {
      await expect(pdp.colourSwatch(name).locator('img')).toHaveAttribute('src', /.+/);
    }
  });

  test('Opening a link that specifies a colour shows that colour as selected', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithMultipleColours();
    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    // Pick a colour that is NOT the default, so the deep link proves something.
    const colours = await pdp.offeredColourNames();
    const defaultName = await pdp.selectedColourSwatch.getAttribute('aria-label');
    const target = colours.find((name) => name !== defaultName);
    await pdp.selectColour(target);
    const deepLink = page.url();

    await page.goto(deepLink);
    await pdp.colourSwatchGroup.waitFor({ state: 'visible', timeout: 20000 });

    await expect(pdp.colourSwatch(target)).toHaveAttribute('aria-checked', 'true');
    await expect(pdp.colourSelectedName).toHaveText(target);
  });

  test('Colours can be chosen using only the keyboard', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithMultipleColours();
    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    const startName = await pdp.selectedColourSwatch.getAttribute('aria-label');
    await pdp.focusColourSwatches();
    await page.keyboard.press('ArrowRight');

    const nowName = await pdp.selectedColourSwatch.getAttribute('aria-label');
    expect(nowName).not.toBe(startName);
    await expect(pdp.colourSelectedName).toHaveText(nowName);
    // Focus follows selection, so the arrow keys stay usable without re-tabbing.
    await expect(pdp.colourSwatch(nowName)).toBeFocused();
  });

  test('A colour that cannot be ordered is not offered to the shopper', TAGS, async ({ page }) => {
    const { sku, withheldColourName } = pdpProductWithNonOrderableColour();
    test.skip(!sku, 'No non-orderable-colour product SKU provisioned — set E2E_NON_ORDERABLE_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    // AC5 (BA clarification 2026-08-21) — an unavailable colour is withheld, not disabled.
    const colours = await pdp.offeredColourNames();
    expect(colours.length).toBeGreaterThan(1);
    if (withheldColourName) {
      // The load-bearing assertion. Without it this test passes even if the colour is
      // rendered, because a non-orderable colour can still have a perfectly good image.
      expect(colours).not.toContain(withheldColourName);
      await expect(pdp.colourSwatch(withheldColourName)).toHaveCount(0);
    }
    // Nothing in the group may advertise itself as disabled — there is no disabled state.
    await expect(pdp.colourSwatchGroup.locator('[aria-disabled="true"]')).toHaveCount(0);
    await expect(pdp.colourSwatchGroup.locator('[disabled]')).toHaveCount(0);
  });

  test('A product whose colours are all unavailable shows no colour section at all', TAGS, async ({ page }) => {
    const { sku } = pdpProductWithAllColoursWithheld();
    test.skip(!sku, 'No all-withheld-colour product SKU provisioned — set E2E_ALL_WITHHELD_COLOUR_PRODUCT_SKU.');

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    // The `hasOfferedColour` gate: colour data exists but nothing survives the AC5 filter,
    // so the whole block is suppressed — no bare "Colour:" label with nothing beside it.
    await expect(pdp.colourSection).toHaveCount(0);
    await expect(pdp.colourLabel).toHaveCount(0);
    await expect(pdp.colourSwatchGroup).toHaveCount(0);
    // The rest of the PDP is unaffected.
    await expect(pdp.productName).toBeVisible();
    await expect(pdp.productPrice).toBeVisible();
    await expect(pdp.productDescription).toBeVisible();
  });

  test('Product information still displays when a product has no colour data', TAGS, async ({ page }) => {
    const { sku } = standardProduct();

    const pdp = new ProductPage(page);
    await pdp.goToProduct(sku);

    // The standard fixture is single-SKU with no colour variations recorded.
    await expect(pdp.productName).toBeVisible();
    await expect(pdp.productPrice).toBeVisible();
    await expect(pdp.productDescription).toBeVisible();
    await expect(pdp.colourSection).toHaveCount(0);
  });
});

