const { BasePage } = require('./BasePage');

class ProductPage extends BasePage {
  constructor(page) {
    super(page);
    this.addToCartButton = page.getByRole('button', { name: /add to cart/i });
    this.productName = page.getByTestId('product-name');
    this.productPrice = page.getByTestId('product-price');
    this.productDescription = page.getByTestId('product-description');
    this.salePrice = page.getByTestId('sale-price');
    this.originalPrice = page.getByTestId('original-price');
    this.outOfStockMessage = page.getByTestId('out-of-stock');
    this.cartDrawer = page.getByTestId('cart-drawer');
  }

  async selectVariant(attribute, value) {
    await this.page.getByRole('radio', { name: value, exact: true }).click();
  }

  async addToCart() {
    await this.addToCartButton.click();
    await this.page.waitForLoadState();
  }

  async goToProduct(sku) {
    // SFCC product URLs use the product ID as part of the path
    // Confirm URL pattern with integration team for the Zimmermann site config
    await this.goto(`/products/${sku}`);
  }
}

module.exports = { ProductPage };

/*
 * Product fixtures for Zimmermann e2e tests.
 * SKUs are configured via env vars — the fallback values are placeholders only.
 * Regional pricing must be kept in sync with SIT Business Manager data.
 * Update REGIONAL_PRICES whenever pricing is changed in the SIT catalogue.
 */

const { activeSiteKey } = require('./site');

// Amounts in local currency, no symbol — formatting is handled by the storefront.
// Keyed by the same 11 fixture keys as sitePrefixes.js/site.generated.js — this
// used to have only 6 keys (au/us/uk/eu/me/hk), and 'eu' was never a real site
// key (site.overlay.js's own comment: the 4 EU-locale sites are 4 separate keys,
// not one shared 'eu' key). price() crashed on undefined for usIntl/enEu/frEu/
// itEu/esEu/euIntl as a result — found 2026-08-26 during an e2e suite review,
// before any PDP/checkout spec existed to actually hit it.
//
// The newly-added keys below reuse the value from the existing entry sharing
// that site's real currency per site.generated.js's live SFCC sync (usIntl is
// USD like us; enEu/frEu/itEu/esEu/euIntl are all EUR) — grounded in real
// currency data, not a guess, but still a provisional stand-in: two markets
// sharing a currency can still have genuinely different local prices per this
// file's own "must be kept in sync with SIT Business Manager data" rule.
// Confirm with the integration team before any test asserts an exact price for
// one of these markets.
//
// Flagged, not fixed here: hk (1850/1295) and me (240/168) below look like
// they were written assuming HKD and AED respectively — but site.generated.js
// says hk and me are actually priced in USD and EUR. Whether the numeric
// values need to change, not just their assumed currency, is a real open
// question for the integration team.
const REGIONAL_PRICES = {
  au: { standard: 350, sale: 245 },
  us: { standard: 240, sale: 168 },
  usIntl: { standard: 240, sale: 168 },
  uk: { standard: 195, sale: 137 },
  enEu: { standard: 220, sale: 154 },
  frEu: { standard: 220, sale: 154 },
  itEu: { standard: 220, sale: 154 },
  esEu: { standard: 220, sale: 154 },
  euIntl: { standard: 220, sale: 154 },
  hk: { standard: 1850, sale: 1295 },
  me: { standard: 240, sale: 168 },
};

const price = (type) => REGIONAL_PRICES[activeSiteKey()][type];

const standardProduct = () => ({
  sku: process.env.E2E_STANDARD_PRODUCT_SKU || 'ZIM-TEST-001',
  inStock: true,
  price: price('standard'),
});

const multiVariantProduct = () => ({
  sku: process.env.E2E_VARIANT_PRODUCT_SKU || 'ZIM-TEST-002',
  inStock: true,
  variants: {
    color: ['Black', 'White'],
    size: ['XS', 'S', 'M', 'L', 'XL'],
  },
  price: price('standard'),
});

const outOfStockProduct = () => ({
  sku: process.env.E2E_OOS_PRODUCT_SKU || 'ZIM-TEST-OOS',
  inStock: false,
});

const saleProduct = () => ({
  sku: process.env.E2E_SALE_PRODUCT_SKU || 'ZIM-TEST-SALE',
  inStock: true,
  isSale: true,
  price: price('sale'),
  originalPrice: price('standard'),
});

